/* Camicat: CPU triangle projection fallback when WebGL is unavailable.
   Uses the same Three.js geometry, perspective camera and object transforms. */
export class CanvasJewelRenderer {
 constructor(T){this.T=T;this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d',{alpha:true});if(!this.ctx)throw Error('Canvas unavailable');this.ratio=1;this.cache=new WeakMap();this.isFallback=true;this.w=1;this.h=1;}
 setPixelRatio(r){this.ratio=Math.min(r,1.25);}
 setClearColor(){}
 setSize(w,h){this.w=w;this.h=h;this.domElement.width=Math.round(w*this.ratio);this.domElement.height=Math.round(h*this.ratio);}
 render(scene,camera){const T=this.T,ctx=this.ctx,w=this.w,h=this.h;ctx.setTransform(this.ratio,0,0,this.ratio,0,0);ctx.clearRect(0,0,w,h);scene.updateMatrixWorld(true);camera.updateMatrixWorld();const pv=new T.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),faces=[];
 scene.traverse(mesh=>{if(!mesh.isMesh||!mesh.visible)return;const geo=mesh.geometry;let cached=this.cache.get(geo);if(!cached){const p=geo.attributes.position,n=geo.attributes.normal,idx=geo.index;cached={points:[],normals:[],indices:idx?Array.from(idx.array):Array.from({length:p.count},(_,i)=>i)};for(let i=0;i<p.count;i++){cached.points.push(new T.Vector3().fromBufferAttribute(p,i));cached.normals.push(n?new T.Vector3().fromBufferAttribute(n,i):new T.Vector3(0,0,1));}this.cache.set(geo,cached);}
 const mvp=new T.Matrix4().multiplyMatrices(pv,mesh.matrixWorld),normal=new T.Matrix3().getNormalMatrix(mesh.matrixWorld),projected=cached.points.map(p=>p.clone().applyMatrix4(mvp)),normals=cached.normals.map(p=>p.clone().applyMatrix3(normal).normalize()),mat=mesh.material,color=mat.color.clone().convertLinearToSRGB(),gold=mat.metalness>.8;const ids=cached.indices;
 for(let i=0;i<ids.length;i+=3){const a=projected[ids[i]],b=projected[ids[i+1]],c=projected[ids[i+2]];if(a.z>1||b.z>1||c.z>1)continue;const cross=(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);if(cross<0)continue;const n=normals[ids[i]].clone().add(normals[ids[i+1]]).add(normals[ids[i+2]]).normalize();const diffuse=Math.max(0,n.x*-.45+n.y*.65+n.z*.61),spec=Math.pow(Math.max(0,n.x*-.35+n.y*.4+n.z*.85),gold?18:40),rim=Math.pow(1-Math.abs(n.z),3);let light=.27+diffuse*.72+rim*.2;let shine=spec*(gold?1.05:.75);if(gold){light+=Math.pow(Math.max(0,Math.cos((n.x+n.y*.7)*5)),16)*.3;}const r=Math.min(255,Math.round((color.r*light+shine)*255)),g=Math.min(255,Math.round((color.g*light+shine*.91)*255)),bl=Math.min(255,Math.round((color.b*light+shine*.7)*255));faces.push({z:(a.z+b.z+c.z)/3,color:`rgb(${r},${g},${bl})`,a:[(a.x*.5+.5)*w,(-a.y*.5+.5)*h],b:[(b.x*.5+.5)*w,(-b.y*.5+.5)*h],c:[(c.x*.5+.5)*w,(-c.y*.5+.5)*h]});}
 });faces.sort((a,b)=>b.z-a.z);for(const f of faces){ctx.fillStyle=f.color;ctx.beginPath();ctx.moveTo(...f.a);ctx.lineTo(...f.b);ctx.lineTo(...f.c);ctx.closePath();ctx.fill();} }
}
